gG1(){return"\u0907\u0938 \u0938\u0902\u0938\u093e\u0927\u0928 \u0915\u0940 \u0905\u0927\u093f\u0915\u0924\u092e \u0915\u094d\u0937\u092e\u0924\u093e, \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902\u0964 100% \u0915\u093e \u0905\u0930\u094d\u0925 \u092a\u0942\u0930\u094d\u0923\u0915\u093e\u0932\u093f\u0915 \u0939\u0948, 200% \u0915\u093e \u0905\u0930\u094d\u0925 \u0926\u094b \u092a\u0942\u0930\u094d\u0923\u0915\u093e\u0932\u093f\u0915 \u0938\u092e\u0915\u0915\u094d\u0937 \u0939\u0948\u0964"},
gG3(){return"\u0913\u0935\u0930\u091f\u093e\u0907\u092e \u0926\u0930:"},
gG4(){return"\u091c\u092c \u092f\u0939 \u0938\u0902\u0938\u093e\u0927\u0928 \u092e\u093e\u0928\u0915 \u0918\u0902\u091f\u094b\u0902 \u0938\u0947 \u0905\u0927\u093f\u0915 \u0915\u093e\u092e \u0915\u0930\u0924\u093e \u0939\u0948 \u0924\u094b \u0932\u093e\u0917\u0942 \u0939\u094b\u0928\u0947 \u0935\u093e\u0932\u0940 \u092a\u094d\u0930\u0924\u093f \u0918\u0902\u091f\u093e \u0926\u0930\u0964"},
gFM(){return"\u0905\u092a\u0935\u093e\u0926:"},
gFN(){return"\u0907\u0938 \u0938\u0902\u0938\u093e\u0927\u0928 \u0915\u0947 \u0932\u093f\u090f \u0915\u0938\u094d\u091f\u092e \u0917\u0948\u0930-\u0915\u093e\u0930\u094d\u092f \u092f\u093e \u0906\u0902\u0936\u093f\u0915 \u0915\u093e\u0930\u094d\u092f \u0926\u093f\u0935\u0938, \u091c\u0948\u0938\u0947 \u091b\u0941\u091f\u094d\u091f\u093f\u092f\u093e\u0901, \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0905\u0935\u0915\u093e\u0936, \u092f\u093e \u0915\u092e \u0918\u0902\u091f\u0947\u0964"},
gG7(){return"\u0938\u0902\u0938\u093e\u0927\u0928 \u092a\u094d\u0930\u0915\u093e\u0930:"},
gGc(){return"\u092f\u0939 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u0938\u0902\u0938\u093e\u0927\u0928 \u0915\u0948\u0938\u0947 \u0936\u0947\u0921\u094d\u092f\u0942\u0932, \u0932\u093e\u0917\u0924 \u0914\u0930 \u091f\u094d\u0930\u0948\u0915 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0915\u093e\u0930\u094d\u092f \u0938\u0902\u0938\u093e\u0927\u0928 \u0936\u094d\u0930\u092e \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0938\u0902\u0938\u093e\u0927\u0928 \u0909\u092a\u092d\u094b\u0917\u094d\u092f \u0906\u092a\u0942\u0930\u094d\u0924\u093f \u0939\u0948\u0902, \u0914\u0930 \u0932\u093e\u0917\u0924 \u0938\u0902\u0938\u093e\u0927\u0928 \u0916\u0930\u094d\u091a\u094b\u0902 \u0915\u093e \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964"},
gnv(){return"\u092c\u0941\u0915\u093f\u0902\u0917 \u092a\u094d\u0930\u0915\u093e\u0930"},
