gy4(){return"\u091a\u0947\u0915 \u0939\u094b\u0928\u0947 \u092a\u0930, \u0915\u0947\u0935\u0932 \u0932\u0941\u0915\u0905\u092a \u0924\u093e\u0932\u093f\u0915\u093e \u0915\u0947 \u092e\u093e\u0928 \u0905\u0938\u093e\u0907\u0928 \u0915\u093f\u090f \u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u092b\u093c\u0940\u0932\u094d\u0921 \u092b\u094d\u0930\u0940-\u092b\u093c\u0949\u0930\u094d\u092e \u0907\u0928\u092a\u0941\u091f \u0915\u0947 \u092c\u091c\u093e\u092f \u0921\u094d\u0930\u0949\u092a\u0921\u093e\u0909\u0928 \u092c\u0928 \u091c\u093e\u0924\u0940 \u0939\u0948\u0964"},
gxT(){return"\u091a\u0947\u0915 \u0939\u094b\u0928\u0947 \u092a\u0930, \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0932\u0941\u0915\u0905\u092a \u0924\u093e\u0932\u093f\u0915\u093e \u092e\u0947\u0902 \u0928\u0939\u0940\u0902 \u092e\u094c\u091c\u0942\u0926 \u092e\u093e\u0928 \u0926\u0930\u094d\u091c \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0935\u0947 \u092e\u093e\u0928 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u0930\u0942\u092a \u0938\u0947 \u0938\u0942\u091a\u0940 \u092e\u0947\u0902 \u091c\u094b\u0921\u093c \u0926\u093f\u090f \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964"},
gAS(){return"\u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921"},
gFJ(){return"\u0932\u093e\u0917\u0924"},
gFF(){return"\u0932\u093e\u0917\u0924 \u0926\u0930 \u0924\u093e\u0932\u093f\u0915\u093e:"},
